const eventTemplates = window.kplEventTemplates;
const eventTemplatesGroups = {
  league: document.querySelector("#league-templates"),
  cup: document.querySelector("#cup-templates")
};
for (const layout of Object.values(eventTemplates)) {
  const group = layout.label.includes("KPL") ? eventTemplatesGroups.league : eventTemplatesGroups.cup;
  group.append(new Option(layout.label, layout.id));
}
const templateDates = {
  classic2018spring: "2018-03-21", classic2018fall: "2018-09-12",
  classic2019spring: "2019-03-06", classic2019fall: "2019-09-11",
  challenge2025: "2025-12-01", grand2026: "2026-10-02"
};
for (const layout of Object.values(eventTemplates)) templateDates[layout.id] = layout.eventDate;
const chronologicalOptions = [...templatePicker.querySelectorAll("option")].sort((a, b) =>
  (templateDates[a.value] || "").localeCompare(templateDates[b.value] || "") ||
  Number(/ · 决赛|final/i.test(a.text)) - Number(/ · 决赛|final/i.test(b.text)) || a.text.localeCompare(b.text, "zh-CN"));
window.kplTemplateDates = templateDates;
const templateOptions = new Map(chronologicalOptions.map((option, index) => [option.value, {
  label: option.text, order: index
}]));
const templateFamilyByVersion = new Map();
const familyIds = new Set();
const templateFamilies = (window.kplTemplateFamilies || []).map(source => {
  if (!source.id || familyIds.has(source.id)) throw new Error("版式编号重复或为空：" + source.id);
  familyIds.add(source.id);
  const variants = [...new Set(source.variants || [])];
  if (!variants.length) throw new Error("版式没有赛事版本：" + source.id);
  for (const id of variants) {
    if (!templateOptions.has(id)) throw new Error("版式包含未知赛事版本：" + id);
    if (templateFamilyByVersion.has(id)) throw new Error("赛事版本重复归类：" + id);
    templateFamilyByVersion.set(id, source.id);
  }
  variants.sort((a, b) => templateOptions.get(a).order - templateOptions.get(b).order);
  if (source.defaultVariant && !variants.includes(source.defaultVariant)) throw new Error("默认赛事版本不属于该版式：" + source.id);
  return { ...source, variants };
});
for (const [id, option] of templateOptions) {
  if (templateFamilyByVersion.has(id)) continue;
  const familyId = "version-" + id;
  if (familyIds.has(familyId)) throw new Error("版式编号重复：" + familyId);
  familyIds.add(familyId);
  templateFamilyByVersion.set(id, familyId);
  templateFamilies.push({ id: familyId, label: option.label, variants: [id] });
}
templateFamilies.sort((a, b) => templateOptions.get(a.variants[0]).order - templateOptions.get(b.variants[0]).order);
const familiesById = new Map(templateFamilies.map(family => [family.id, family]));
const familySelections = new Map();
familyPicker.replaceChildren(...templateFamilies.map(family => new Option(family.label, family.id)));
window.kplTemplateFamilies = templateFamilies;
window.kplTemplateVersions = chronologicalOptions.map(option => ({
  id: option.value, label: option.text, date: templateDates[option.value], familyId: templateFamilyByVersion.get(option.value)
}));

function populateTemplateVersions(familyId, preferredVersion) {
  const family = familiesById.get(familyId);
  if (!family) throw new RangeError("未知版式：" + familyId);
  const selected = preferredVersion || familySelections.get(familyId) || family.defaultVariant || family.variants[0];
  if (!family.variants.includes(selected)) throw new RangeError("赛事版本不属于该版式：" + selected);
  familyPicker.value = familyId;
  templatePicker.replaceChildren(...family.variants.map(id => new Option(templateOptions.get(id).label, id)));
  templatePicker.value = selected;
  familySelections.set(familyId, selected);
  versionField.hidden = family.variants.length < 2;
  familyHint.hidden = family.variants.length < 2;
  familyHint.textContent = family.variants.length > 1
    ? "同一版式共 " + family.variants.length + " 个赛事版本，切换后保留各赛事的背景、字体和细节。" : "";
}

populateTemplateVersions(templateFamilyByVersion.get("grand2026"), "grand2026");
familyPicker.addEventListener("change", () => {
  populateTemplateVersions(familyPicker.value);
  templatePicker.dispatchEvent(new Event("change", { bubbles: true }));
});
window.kplSelectTemplate = function selectTemplate(id) {
  const familyId = templateFamilyByVersion.get(id);
  if (!familyId) throw new RangeError("未知赛事版本：" + id);
  populateTemplateVersions(familyId, id);
  templatePicker.dispatchEvent(new Event("change", { bubbles: true }));
  return id;
};
