function leaveReferenceSampleMode() {
  referenceSampleMode = false;
  document.querySelector("#honor-source-hint").hidden = true;
}

function showGrandPortrait() {
  return grandPortraitPreference ?? !(grandBackground && isDemo);
}

function clearGrandBackground() {
  grandBackgroundRequest++;
  grandBackground = null;
  grandBackgroundInput.value = "";
  grandBackgroundReset.hidden = true;
  grandBackgroundStatus.textContent = "";
}

grandBackgroundInput.addEventListener("change", async () => {
  const file = grandBackgroundInput.files[0];
  grandBackgroundInput.value = "";
  if (!file) return;
  const request = ++grandBackgroundRequest;
  grandBackgroundReset.hidden = false;
  grandBackgroundStatus.textContent = "正在读取背景图片…";
  const url = URL.createObjectURL(file);
  const image = new Image();
  image.src = url;
  try {
    await image.decode();
    if (request !== grandBackgroundRequest) return;
    grandBackground = image;
    grandBackgroundStatus.textContent = "已使用自定义背景。";
    draw();
  } catch {
    if (request !== grandBackgroundRequest) return;
    grandBackgroundReset.hidden = !grandBackground;
    grandBackgroundStatus.textContent = "背景图片读取失败，请换一张 JPG、PNG 或 WebP。";
  } finally {
    URL.revokeObjectURL(url);
  }
});

grandBackgroundReset.addEventListener("click", () => {
  clearGrandBackground();
  draw();
});

grandPortraitToggle.addEventListener("change", () => {
  grandPortraitPreference = grandPortraitToggle.checked;
  draw();
});

let drag = null;
let templateFontsReady = Promise.resolve();
const templateFontLoads = new Map();

function prepareTemplateFonts(template, layout) {
  const styles = layout ? Object.values(layout.fields).map(field => ({
    family: field.fontFamily, weight: field.weight || 700, italic: field.italic
  })) : template === "challenge2025" ? [
    { family: "KplDisplayCJK", weight: 700 }, { family: "KplCJK", weight: 700 }
  ] : [];
  const numericStyle = window.kplTypeGlyphs?.families?.[window.kplTypeGlyphs.templates?.[template]];
  if (numericStyle) styles.push(numericStyle);
  const classicTypeReady=template === "classic2018spring" ? Promise.all([
    window.kplClassicIdentityReady,
    document.fonts.load('400 15.3px "Microsoft YaHei"',"北京久诚无畏杨涛浙江"),
    document.fonts.load('400 15.3px "KplCJK"',"北京久诚无畏杨涛浙江")
  ]) : Promise.resolve();
  templateFontsReady = Promise.all([classicTypeReady,window.kplHonorAssetsReady,window.kplCityTypeReady,...styles.filter(style => style.family?.startsWith("Kpl")).map(style => {
    const key = (style.italic ? "italic " : "") + style.weight + ' 28px "' + style.family + '"';
    if (!templateFontLoads.has(key)) templateFontLoads.set(key,
      document.fonts.load(key, "北京JDG无畏杨涛力挽狂澜0123456789%").catch(() => []));
    return templateFontLoads.get(key);
  })]).then(() => { if (templatePicker.value === template) draw(); });
}
document.fonts.addEventListener("loadingdone", draw);

function crop() {
  return Object.fromEntries(Object.entries(controls).map(([key, control]) => [key, Number(control.value)]));
}

function resetCrop() {
  controls.x.value = 0;
  controls.y.value = 0;
  controls.zoom.value = 1;
}

